<script lang="ts">
  import { invoke } from "@tauri-apps/api/core";
  import { listen } from "@tauri-apps/api/event";
  import { open as openFolderDialog } from "@tauri-apps/plugin-dialog";
  import { onMount, onDestroy } from "svelte";

  type Page = "update" | "game" | "tweaks" | "mods" | "addons" | "activity";
  type Phase = "ready" | "needsConfiguration" | "preparing" | "recovering" | "failed";
  type Status = { phase: Phase; message: string; gameDirectory?: string; interruptedTransactions: number };
  type Plan = { id: string; gameDirectory: string; manifest: { sha256: string; totalBytes: number; files: { path: string; length: number }[] }; selection: { missingFiles: number; mismatchedFiles: number; selectedFiles: number; selectedBytes: number }; manifestPath: string; planPath: string; journalPath: string };
  type TransactionState = "prepared" | "downloading" | "verifying" | "applying" | "complete" | "cancelled" | "failed" | "abandoned";
  type ProgressEvent = { id: string; state: TransactionState; message: string; progress: number; bytesDone: number; bytesTotal: number; bytesPerSecond: number };
  type Tweaks = { locale: string; alwaysAutoLoot: boolean; nameplateRange: number; fieldOfView: number; farClip: number; frillDistance: number; cameraDistance: number; soundInBackground: boolean };
  type ModStatus = { id: string; name: string; description: string; essential: boolean; installed: boolean; enabled: boolean; updateAvailable: boolean };
  type AddonStatus = { id: string; name: string; description: string; installed: boolean; updateAvailable: boolean; custom: boolean; repositoryUrl?: string; reference?: string; provider?: "gitHub" | "gitLab" | "gitea"; detected: boolean; managed: boolean };
  type CustomAddonRequest = { repositoryUrl: string; reference?: string; installFolder?: string };
  type LogLevel = "info" | "success" | "warning" | "error";
  type LogEntry = { timestampUnix: number; level: LogLevel; message: string };
  type NewsPost = { id: string; title: string; date: string; author?: string; body: string; url?: string };
  type NewsFeed = { featured: NewsPost | null; patchNotes: NewsPost[] };
  let currentPage = $state<Page>("update"), status = $state<Status>({ phase: "needsConfiguration", message: "Loading updater state…", interruptedTransactions: 0 }), gameDirectory = $state(""), busy = $state(false), notice = $state(""), plan = $state<Plan | null>(null), clientVersion = $state(""), tweaks = $state<Tweaks | null>(null), launchBusy = $state(false), mods = $state<ModStatus[]>([]), modBusyId = $state<string | null>(null), addons = $state<AddonStatus[]>([]), addonBusyId = $state<string | null>(null), customRepositoryUrl = $state(""), customReference = $state(""), customInstallFolder = $state(""), logs = $state<LogEntry[]>([]), showLogs = $state(false), news = $state<NewsFeed | null>(null), newsLoading = $state(false), newsError = $state(""), activeState = $state<TransactionState | null>(null), activeMessage = $state(""), activeProgress = $state(0), activeBytesDone = $state(0), activeBytesTotal = $state(0), activeBytesPerSecond = $state(0);
  let unlisten: (() => void) | null = null, logUnlisten: (() => void) | null = null;
  const RUNNING_STATES: TransactionState[] = ["downloading", "verifying", "applying"];
  const isRunning = $derived(activeState !== null && RUNNING_STATES.includes(activeState));
  const title: Record<Page, string> = { update: "Client update", game: "Game profile", tweaks: "Client tweaks", mods: "Client mods", addons: "Addon library", activity: "Activity" };
  const formatTime = (time: number) => new Date(time * 1000).toLocaleTimeString();
  function formatBytes(bytes: number) { if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 ** 2) return `${(bytes / 1024).toFixed(0)} KB`; if (bytes < 1024 ** 3) return `${(bytes / 1024 ** 2).toFixed(1)} MB`; return `${(bytes / 1024 ** 3).toFixed(2)} GB`; }
  async function refreshStatus() { status = await invoke<Status>("get_updater_status"); gameDirectory = status.gameDirectory ?? gameDirectory; clientVersion = await invoke<string>("get_client_version").catch(() => ""); }
  async function loadTweaks() { tweaks = await invoke<Tweaks>("get_tweaks").catch(() => null); }
  async function loadMods() { mods = await invoke<ModStatus[]>("get_mod_statuses").catch(() => []); }
  async function loadAddons() { addons = await invoke<AddonStatus[]>("get_addon_statuses").catch(() => []); }
  async function loadNews() { newsLoading = true; newsError = ""; try { news = await invoke<NewsFeed>("get_news"); } catch (error) { newsError = String(error); } finally { newsLoading = false; } }
  async function installAddon(addonId: string) { addonBusyId = addonId; notice = ""; try { const updated = await invoke<AddonStatus>("install_addon", { addonId }); addons = addons.map(a => a.id === addonId ? updated : a); notice = `${updated.name} installed.`; } catch (e) { notice = String(e); } finally { addonBusyId = null; } }
  async function uninstallAddon(addonId: string) { addonBusyId = addonId; notice = ""; try { const updated = await invoke<AddonStatus>("uninstall_addon", { addonId }); addons = addons.map(a => a.id === addonId ? updated : a); notice = `${updated.name} removed.`; } catch (e) { notice = String(e); } finally { addonBusyId = null; } }
  async function updateCustomAddon(addonId: string) { addonBusyId = addonId; notice = ""; try { const updated = await invoke<AddonStatus>("update_custom_addon", { addonId }); addons = addons.map(a => a.id === addonId ? updated : a); notice = `${updated.name} updated.`; } catch (e) { notice = String(e); } finally { addonBusyId = null; } }
  async function installCustomAddon() { addonBusyId = "custom-install"; notice = ""; const request: CustomAddonRequest = { repositoryUrl: customRepositoryUrl.trim() }; if (customReference.trim()) request.reference = customReference.trim(); if (customInstallFolder.trim()) request.installFolder = customInstallFolder.trim(); try { const updated = await invoke<AddonStatus>("install_custom_addon", { request }); addons = [...addons.filter(a => a.id !== updated.id), updated]; customRepositoryUrl = customReference = customInstallFolder = ""; notice = `${updated.name} installed from its pinned repository commit.`; } catch (e) { notice = String(e); } finally { addonBusyId = null; } }
  async function installMod(modId: string) { modBusyId = modId; notice = ""; try { const updated = await invoke<ModStatus>("install_mod", { modId }); mods = mods.map(m => m.id === modId ? updated : m); notice = `${updated.name} installed.`; } catch (e) { notice = String(e); } finally { modBusyId = null; } }
  async function uninstallMod(modId: string) { modBusyId = modId; notice = ""; try { const updated = await invoke<ModStatus>("uninstall_mod", { modId }); mods = mods.map(m => m.id === modId ? updated : m); notice = `${updated.name} removed.`; } catch (e) { notice = String(e); } finally { modBusyId = null; } }
  async function saveTweaksNow() { if (!tweaks) return; busy = true; notice = ""; try { tweaks = await invoke<Tweaks>("save_tweaks", { tweaks }); notice = "Tweaks saved. They apply the next time WoW.exe is patched by an update."; } catch (e) { notice = String(e); } finally { busy = false; } }
  async function launchGame() { launchBusy = true; notice = ""; try { notice = `Launched ${await invoke<string>("launch_game")}.`; } catch (e) { notice = String(e); } finally { launchBusy = false; } }
  async function saveGameDirectory() { busy = true; notice = ""; try { status = await invoke<Status>("set_game_directory", { directory: gameDirectory.trim() }); gameDirectory = status.gameDirectory ?? gameDirectory; clientVersion = await invoke<string>("get_client_version").catch(() => ""); notice = "Game folder saved."; } catch (e) { notice = String(e); } finally { busy = false; } }
  async function browseForGameDirectory() { const selected = await openFolderDialog({ directory: true, multiple: false, title: "Choose your OctoWoW installation folder", defaultPath: gameDirectory || undefined }); if (typeof selected === "string") { gameDirectory = selected; await saveGameDirectory(); } }
  async function prepareUpdate() { busy = true; notice = ""; try { plan = await invoke<Plan>("prepare_update"); const size = (plan.selection.selectedBytes / 1024 ** 3).toFixed(2); notice = plan.selection.selectedFiles === 0 ? `Verified manifest ${plan.manifest.sha256.slice(0, 12)}…: everything is already up to date.` : `Verified manifest ${plan.manifest.sha256.slice(0, 12)}…: ${plan.selection.selectedFiles.toLocaleString()} files need syncing (${size} GiB; ${plan.selection.missingFiles} missing, ${plan.selection.mismatchedFiles} wrong-sized).`; await refreshStatus(); } catch (e) { notice = String(e); } finally { busy = false; } }
  async function startUpdate() { if (!plan) return; notice = ""; activeState = "downloading"; activeMessage = "Starting…"; activeProgress = 0; try { await invoke("start_update", { id: plan.id }); } catch (e) { activeState = "failed"; notice = String(e); } }
  async function cancelUpdate() { if (!plan) return; try { await invoke("cancel_update", { id: plan.id }); } catch (e) { notice = String(e); } }
  async function recover() { busy = true; notice = ""; try { status = await invoke<Status>("recover_interrupted_updates"); notice = "Interrupted prepared transactions were recovered safely."; } catch (e) { notice = String(e); } finally { busy = false; } }
  onMount(async () => { await refreshStatus(); await loadTweaks(); await loadMods(); await loadAddons(); await loadNews(); logs = await invoke<LogEntry[]>("get_recent_logs").catch(() => []); unlisten = await listen<ProgressEvent>("update-progress", e => { const p = e.payload; if (plan && p.id !== plan.id) return; activeState = p.state; activeMessage = p.message; activeProgress = p.progress; activeBytesDone = p.bytesDone; activeBytesTotal = p.bytesTotal; activeBytesPerSecond = p.bytesPerSecond; if (["complete", "failed", "cancelled"].includes(p.state)) { refreshStatus(); if (p.state === "complete") loadMods(); } }); logUnlisten = await listen<LogEntry>("app-log", e => { logs = [...logs, e.payload].slice(-200); }); });
  onDestroy(() => { unlisten?.(); logUnlisten?.(); });
</script>
<svelte:head><title>OctoWoW Client Manager</title></svelte:head>
<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="mark">◉<i></i><i></i><i></i></div><div><p class="eyebrow">OCTOWOW</p><h1>Client<br />Manager</h1></div></div><nav aria-label="Launcher pages">{#each [["update", "↻", "Update", "Sync your client"], ["game", "▣", "Game", "Installation & launch"], ["tweaks", "⚙", "Tweaks", "Client configuration"], ["mods", "✦", "Mods", "Enhance your client"], ["addons", "▦", "Addons", "Library & repositories"], ["activity", "◷", "Activity", "Session event log"]] as item}<button class:active={currentPage === item[0]} class="nav-button" onclick={() => currentPage = item[0] as Page}><b>{item[1]}</b><span><strong>{item[2]}</strong><small>{item[3]}</small></span>{#if item[0] === "activity"}<em>{logs.length}</em>{:else if item[0] === "update" && isRunning}<em>{Math.round(activeProgress * 100)}%</em>{/if}</button>{/each}</nav><div class="sidebar-launch"><button onclick={launchGame} disabled={launchBusy || isRunning || !status.gameDirectory}>▶ {launchBusy ? "Launching…" : "Play OctoWoW"}</button></div><div class="side-bottom"><i class:alert={status.phase === "recovering" || status.phase === "failed"}></i><div><strong>{status.gameDirectory ? "Client detected" : "Client not configured"}</strong><small>{status.phase}</small></div></div></aside>
<main><header class="topbar"><div><p class="eyebrow">OCTOWOW LAUNCHER</p><h2>{title[currentPage]}</h2></div><span class="live"><i></i>{isRunning ? "Update in progress" : status.phase === "ready" ? "System ready" : "Awaiting setup"}</span></header>{#if notice}<p class="notice" role="status">{notice}</p>{/if}
{#if currentPage === "update"}<section class="hero"><img src="/Turtle_Wow_Anniversary_Illustration-Bb7K3vq-.webp" alt="OctoWoW festival scene" /><div class="hero-copy"><p class="eyebrow">OCTOWOW CLIENT</p><h3>Keep your adventure<br /><em>ready for launch.</em></h3><p>Sync safely with a journaled, recoverable update process built for every interruption.</p><div class="features"><span>✓ Safe</span><span>✓ Reliable</span><span>✓ Recoverable</span></div></div></section><section class="sync card"><div><p class="eyebrow">TRANSACTIONAL SYNC</p><h3>{isRunning ? activeMessage : status.message}</h3><p>Downloads are verified before they are applied. Interrupted updates can be recovered safely.</p>{#if isRunning}<div class="progress"><div><span>{activeState}</span><b>{Math.round(activeProgress * 100)}%</b></div><strong><i style="width: {Math.round(activeProgress * 100)}%"></i></strong><small>{formatBytes(activeBytesDone)} / {formatBytes(activeBytesTotal)}{#if activeBytesPerSecond > 0} · {formatBytes(activeBytesPerSecond)}/s{/if}</small><button class="secondary" onclick={cancelUpdate}>Cancel update</button></div>{:else}<div class="actions"><button onclick={prepareUpdate} disabled={busy || !status.gameDirectory}>{busy ? "Preparing…" : "Check for updates"}</button>{#if plan && plan.selection.selectedFiles > 0 && (!activeState || activeState === "prepared")}<button class="secondary" onclick={startUpdate}>Start update</button>{/if}{#if status.interruptedTransactions > 0}<button class="secondary" onclick={recover}>Recover {status.interruptedTransactions} update(s)</button>{/if}</div>{#if activeState === "complete"}<small class="good">Update complete — your client is ready.</small>{:else if activeState === "failed"}<small class="bad">Update failed. Inspect Activity for details.</small>{/if}{/if}</div><div class="orb">↓<small>SYNC</small></div></section><section class="quick">{#each [["▣", "GAME INSTALLATION", status.gameDirectory ?? "Not configured", "Manage installation", "game"], ["◈", "CLIENT VERSION", clientVersion || "Not detected", "View client tweaks", "tweaks"], ["✦", "CLIENT STATUS", status.phase === "ready" ? "Ready to play" : "Needs attention", "View activity", "activity"]] as card}<article class="card"><i>{card[0]}</i><p>{card[1]}</p><strong>{card[2]}</strong><button onclick={() => currentPage = card[4] as Page}>{card[3]} →</button></article>{/each}</section><section class="news card"><header><div><p class="eyebrow">OCTOWOW NEWS</p><h3>Latest from the realm</h3></div><button class="secondary" onclick={loadNews} disabled={newsLoading}>{newsLoading ? "Refreshing…" : "Refresh"}</button></header>{#if newsError}<p class="news-message">Couldn’t reach the news feed. {newsError}</p>{:else if newsLoading && !news}<p class="news-message">Loading announcements and patch notes…</p>{:else}<div class="news-grid"><article class="featured-news">{#if news?.featured}<p class="news-date">{news.featured.date}{#if news.featured.author} · by {news.featured.author}{/if}</p><h4>{news.featured.title}</h4><p>{news.featured.body || "No announcement text was provided."}</p>{:else}<p class="news-message">No announcements yet — check back soon.</p>{/if}</article><aside class="patch-notes"><p class="eyebrow">PATCH NOTES & DEV UPDATES</p>{#if news?.patchNotes.length}{#each news.patchNotes.slice(0, 3) as post (post.id)}<article><time>{post.date}</time><strong>{post.title}</strong>{#if post.body}<p>{post.body}</p>{/if}</article>{/each}{:else}<p class="news-message">No patch notes are available.</p>{/if}</aside></div>{/if}</section>
{:else if currentPage === "game"}<section class="page card"><p class="eyebrow">INSTALLATION</p><h3>Your game client</h3><p>Choose the folder that contains OctoWoW. Profiles and journals live outside this folder.</p><label for="directory">OctoWoW installation folder</label><div class="directory"><input id="directory" bind:value={gameDirectory} placeholder="C:\\Games\\OctoWoW" disabled={busy || isRunning} /><button class="secondary" onclick={browseForGameDirectory} disabled={busy || isRunning}>Browse</button><button onclick={saveGameDirectory} disabled={busy || isRunning || !gameDirectory.trim()}>Save folder</button></div>{#if clientVersion}<div class="detail"><span>Installed client version</span><strong>{clientVersion}</strong></div>{/if}</section>
{:else if currentPage === "tweaks"}<section class="page card"><p class="eyebrow">CLIENT CONFIGURATION</p><h3>Make the client yours</h3><p>Saved settings are re-applied whenever an update patches WoW.exe.</p>{#if tweaks}<div class="tweaks">{#each [["Field of view", "fieldOfView", 90, 180, 5], ["Camera distance", "cameraDistance", 50, 100, 1], ["World distance", "farClip", 100, 10000, 1], ["Ground clutter distance", "frillDistance", 0, 300, 1], ["Nameplate range", "nameplateRange", 0, 41, 1]] as field}<label>{field[0]}<input type="number" min={field[2]} max={field[3]} step={field[4]} bind:value={tweaks[field[1] as keyof Tweaks]} /></label>{/each}<label class="check"><input type="checkbox" bind:checked={tweaks.alwaysAutoLoot} /> Always auto-loot</label><label class="check"><input type="checkbox" bind:checked={tweaks.soundInBackground} /> Sound in background</label></div><div class="actions"><button onclick={saveTweaksNow} disabled={busy}>Save tweaks</button></div>{:else}<p>Loading tweak settings…</p>{/if}</section>
{:else if currentPage === "mods"}<section class="page card"><p class="eyebrow">MOD LIBRARY</p><h3>Extend your client</h3><p>Close WoW before changing DLL or MPQ mods.</p>{#if mods.length === 0}<p class="empty">No mods are currently available.</p>{:else}<ul>{#each mods as mod (mod.id)}<li><div><strong>{mod.name}{#if mod.essential}<em>essential</em>{/if}</strong><p>{mod.description}</p></div><aside>{#if mod.updateAvailable}<span>update available</span>{/if}{#if mod.installed}<button class="secondary" onclick={() => uninstallMod(mod.id)} disabled={modBusyId === mod.id || isRunning}>{modBusyId === mod.id ? "Working…" : "Remove"}</button>{:else}<button onclick={() => installMod(mod.id)} disabled={modBusyId === mod.id || isRunning || !status.gameDirectory}>{modBusyId === mod.id ? "Installing…" : "Install"}</button>{/if}</aside></li>{/each}</ul>{/if}</section>
{:else if currentPage === "addons"}<section class="page card"><p class="eyebrow">ADDON LIBRARY</p><h3>Curated and custom addons</h3><p>Custom repositories can use GitHub, GitLab, Codeberg, or gitea.com. Only add repositories you trust.</p><div class="repo"><label>Repository URL<input bind:value={customRepositoryUrl} placeholder="https://github.com/owner/repository" /></label><label>Branch, tag, or commit<input bind:value={customReference} placeholder="Default branch" /></label><label>Install folder<input bind:value={customInstallFolder} placeholder="Repository name" /></label><button class="secondary" onclick={installCustomAddon} disabled={addonBusyId === "custom-install" || isRunning || !status.gameDirectory || !customRepositoryUrl.trim()}>{addonBusyId === "custom-install" ? "Installing…" : "Add repository"}</button></div>{#if addons.length === 0}<p class="empty">No addons detected or configured.</p>{:else}<ul>{#each addons as addon (addon.id)}<li><div><strong>{addon.name}{#if addon.custom}<em>custom</em>{/if}</strong><p>{addon.description}{#if addon.repositoryUrl} · {addon.repositoryUrl}{#if addon.reference} @ {addon.reference}{/if}{/if}</p></div><aside>{#if addon.installed}{#if addon.managed}{#if addon.custom}<button class="secondary" onclick={() => updateCustomAddon(addon.id)} disabled={addonBusyId === addon.id || isRunning}>Update</button>{/if}<button class="secondary" onclick={() => uninstallAddon(addon.id)} disabled={addonBusyId === addon.id || isRunning}>Remove</button>{:else}<span>detected locally</span>{/if}{:else}<button onclick={() => installAddon(addon.id)} disabled={addonBusyId === addon.id || isRunning || !status.gameDirectory}>Install</button>{/if}</aside></li>{/each}</ul>{/if}</section>
{:else}<section class="page card"><header><div><p class="eyebrow">SESSION LOG</p><h3>Recent launcher activity</h3></div><button class="secondary" onclick={() => showLogs = !showLogs}>{showLogs ? "Hide log" : `Show log (${logs.length})`}</button></header>{#if showLogs}<div class="logs">{#if logs.length === 0}<p class="empty">No activity yet this session.</p>{:else}{#each logs.slice().reverse() as entry}<p class={entry.level}><time>{formatTime(entry.timestampUnix)}</time>{entry.message}</p>{/each}{/if}</div>{:else}<p>Open the session log to inspect update, mod, addon, and launch events.</p>{/if}</section>{/if}<footer>OCTOWOW CLIENT MANAGER <span>Transactional update system · {clientVersion || "Client version unavailable"}</span></footer></main></div>
<style>
